    # Use depth-first search (DFS) to find a path
    def dfs(current: Tuple[int, int], path: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        row, col = current
        if current == goal:
            return path + [current]

        # Mark the current cell as visited
        grid[row] = grid[row][:col] + '#' + grid[row][col+1:]

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == '.':
                result = dfs((new_row, new_col), path + [current])
                if result:
